prefix=s[:s.index('\nfor(const size')]
part=s[s.index('\nconst { setupIndex }'):s.index("\ntest('review DeoVR Index: connect")]
body=prefix+part
body=body.replace("'../entry/",repr((root/'ohos/entry').as_uri()+'/')[:-1]).replace("'./index-controller-helpers.mjs'",repr((root/'ohos/tests/index-controller-helpers.mjs').as_uri())).replace("'./output-owner-helpers.mjs'",repr((root/'ohos/tests/output-owner-helpers.mjs').as_uri()))
body += '\n' + "const { ShortcutAction, shortcutActionCatalog, cloneShortcutAction, defaultShortcutAction, KeyboardShortcutMapping, KeyboardShortcutConfiguration } = await import('"+(root/'ohos/entry/src/main/ets/input/ShortcutConfiguration.ts').as_uri()+"');\n"
body += "const { ShortcutKeyEvent } = await import('"+(root/'ohos/entry/src/main/ets/input/LocalShortcutEngine.ts').as_uri()+"');\n"
body += r'''
const connectionIds=['Internal','DeoVR'].flatMap(source=>['Toggle','Connect','Disconnect'].map(command=>source+'::Connection::'+command));
const action=(id,text='')=>{const a=defaultShortcutAction(id);a.text=text;return a;};
async function invoke(h,id,via='direct',text=''){
 const a=action(id,text);
 if(via==='touch')return h.page.touchShortcut(a);
 if(via==='keyboard'){
  const config=new KeyboardShortcutConfiguration();const mapping=new KeyboardShortcutMapping('audit-action','action probe');mapping.keys=[2017];mapping.trigger='press';mapping.actions=[a];config.mappings=[mapping];
  h.page.keyboard.setConfiguration(config);h.page.updateKeyboardContext();
  const dispatches=h.page.keyboard.keyEvent(new ShortcutKeyEvent(2017,true),h.time.now);
  assert.equal(dispatches.length,1,'real keyboard engine must produce dispatch');
  await h.page.runShortcutDispatch(dispatches[0]);h.page.keyboard.keyEvent(new ShortcutKeyEvent(2017,false),++h.time.now);return;
 }
 return h.page.executeShortcutAction(a,'L0');
}
test('coverage probe: eight source-action specs retain exact arguments, categories and non-axis/non-output traits',()=>{
 const catalog=shortcutActionCatalog();assert.equal(new Set(catalog.map(s=>s.id)).size,catalog.length);
 for(const id of connectionIds.concat(['DeoVR::Endpoint::Set','Media::Path::Set'])){
  const s=catalog.find(s=>s.id===id);assert.ok(s);assert.equal(s.originalName,id);assert.equal(s.category,'source');
  assert.equal(s.targetAxis,false);assert.equal(s.targetOutput,false);assert.equal(s.managedScript,false);assert.equal(s.pointsKind,'none');
  assert.equal(s.minimum,0);assert.equal(s.maximum,0);assert.equal(s.secondaryValueKind,'none');assert.equal(s.tertiaryValueKind,'none');
  assert.equal(s.valueKind,connectionIds.includes(id)?'none':'text');assert.doesNotThrow(()=>cloneShortcutAction(action(id)));
  for(const field of ['targetAxis','outputTargetId','points','value']){const a=action(id);a[field]=field==='targetAxis'?'L0':field==='outputTargetId'?'tcp:0':field==='points'?[{x:0,y:.5}]:1;assert.throws(()=>cloneShortcutAction(a));}
 }
 for(const id of connectionIds){assert.throws(()=>cloneShortcutAction(action(id,'not accepted')));}
 for(const [id,max] of [['DeoVR::Endpoint::Set',280],['Media::Path::Set',4096]]){
  assert.equal(catalog.find(s=>s.id===id).maximumTextLength,max);assert.doesNotThrow(()=>cloneShortcutAction(action(id,'x'.repeat(max))));
  assert.throws(()=>cloneShortcutAction(action(id,'x'.repeat(max+1))));assert.throws(()=>cloneShortcutAction(action(id,'x\n')));
 }
