});
for(const sourceName of ['Internal','DeoVR'])for(const via of ['touch','keyboard'])test(`coverage probe: ${sourceName} six-state connection lifecycle via actual ${via} dispatch`,async()=>{
 const h=pageHarness();const connected=()=>sourceName==='Internal'?h.page.internalConnected:h.page.deoVrConnected;
 try{
  await invoke(h,sourceName+'::Connection::Disconnect',via);assert.equal(connected(),false);
  await invoke(h,sourceName+'::Connection::Connect',via);assert.equal(connected(),true);
  const ports=h.ports.length;await invoke(h,sourceName+'::Connection::Connect',via);assert.equal(connected(),true);assert.equal(h.ports.length,ports);
  await invoke(h,sourceName+'::Connection::Toggle',via);assert.equal(connected(),false);
  await invoke(h,sourceName+'::Connection::Toggle',via);assert.equal(connected(),true);
  await invoke(h,sourceName+'::Connection::Disconnect',via);assert.equal(connected(),false);assert.equal(h.outputPorts.length,0);
 }finally{await cleanPage(h);}
